数据库表结构已经确定（表名、列名须与之对应；SIR 中不写 SQL）：
-- Conformance fixture DDL for the Course Admin write slice (Q10).
--
-- This schema is TEST_FIXTURE_DDL, not a product capability: the generated
-- application has no INITIALIZE/UPDATE support (those belong to G3), so the
-- harness owns the schema and its rows, and every assertion is read back over an
-- independent JDBC connection.
--
-- `version` is the concurrency token the SIR entity declares as `versioned`. It is
-- NOT NULL with a default, which is what lets the first change on a row be matched
-- against the value a fresh insert started at.

CREATE TABLE course (
    id BIGINT NOT NULL AUTO_INCREMENT,
    code VARCHAR(32) NOT NULL,
    name VARCHAR(100) NOT NULL,
    description VARCHAR(500) NULL,
    capacity INT NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);

已有软件（返回修改后的完整文档）：
sir 0.3

software CourseAdmin {
  metadata {
    displayName "Course Admin";
    namespace "com.example.courseadmin";
  }

  target {
    language java 21;
    framework spring_boot;
    persistence mybatis_plus;
    database mysql;
    build maven;
    interface rest;
  }

  sources { }
  imports { }
  declarations {
    entity Course persistent {
      identity id: Id generated auto;
      field code: Code;
      field name: Name;
      field description: Optional<Remark>;
      field capacity: Quantity;
      field version: Version;
    }
    view CourseDetail from Course {
      field id: Id;
      field code: Text;
      field name: Text;
      field description: Optional<Text>;
      field capacity: Count;
      field version: Serial;
    }
    input GetCourseInput {
      field id: Id;
    }
    input CreateCourseInput {
      field code: Code;
      field name: Name;
      field description: Optional<Remark>;
      field capacity: Quantity;
    }
    error CourseNotFound http 404;
    capability GetCourse {
      input GetCourseInput;
      output CourseDetail;
      fails CourseNotFound;
      requires readonly;
      expose query;
      workflow {
        load Course by input.id as course else CourseNotFound;
        return course;
      }
    }
    capability CreateCourse {
      input CreateCourseInput;
      output CourseDetail;
      requires atomic;
      expose command;
      workflow {
        create Course as created {
          code: input.code;
          name: input.name;
          description: input.description;
          capacity: input.capacity;
        }
        persist created;
        return created;
      }
    }
  }
}

